import assert from 'node:assert/strict';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { pathToFileURL } from 'node:url';

import { renderSpecLine } from './speckit-prepare-core.mjs';
import { presentAmendment, resolveAmendment, runRecordAnalysis, startRework } from './speckit-amend.mjs';
import { ATTENTION_LABEL, BLOCKED_LABEL, DIAGNOSIS_COMMENT_MARKER, RETRY_COMMENT_MARKER, maintainDependencyBlock, parseFixEvents, renderFixEvent, setAttention, setBlocked } from './speckit-implement-core.mjs';
import { authoredFor, checkFixSpec, main as fixMain, designDecisionsFromPlan, fixBlock, fixStamp, isAutomationCommit, linkPrerequisite, maintainFixSpec, parseAuthorReport, parseDesignDecisions, readResult, reworkOutcome, reworkStage, runDecide, runEvidence, runInputs, runLand, runPackage, runRecord, settleClosedFix, startFixAuthoring, syncDesignDecisions, validateDecision } from './speckit-fix.mjs';
import { defaultGit } from './speckit-orchestrate.mjs';
import { diagnosisRepo, silent } from './speckit-test-helpers.mjs';

const FOLDER = '20261014-100000-upload-expiry';
const PREFIX = `specs/${FOLDER}`;
const BRANCH = `speckit-spec/${FOLDER}`;

// The workflow_dispatch inputs an agentic workflow declares in its frontmatter.
function declaredInputs(file) {
  const source = readFileSync(new URL(`../workflows/${file}`, import.meta.url), 'utf8').replaceAll('\r\n', '\n');
  const block = source.match(/\n {4}inputs:\n([\s\S]*?)\n {2}\S/)?.[1] ?? '';
  return [...block.matchAll(/^ {6}([a-z_]+):$/gm)].map((match) => match[1]);
}
const env = (extra = {}) => ({ GITHUB_REPOSITORY: 'octo/repo', SPECKIT_DEFAULT_BRANCH: 'main', SPECKIT_TWIN: '5', SPECKIT_PULL: '9', SPECKIT_FOLDER: 'f', ...extra });
const SPEC = '# Feature Specification: Upload session expiry test\n\n## Summary\n\nMake the test independent of runner load.\n\n## Assumptions\n\n- `specs/f` depends on this spec.\n';
const PLAN = '# Plan\n\n## Architecture Updates\n\nNone: the fix changes a test only.\n';
const TASKS = '## Phase 1\n\n- [ ] T001 Use a longer SessionLifetime in UploadSessionExpiryTests\n';
// The result of the author job (result.json) in a temporary result folder, for runRecord.
function withResult(result, body) {
  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-result-'));
  try {
    writeFileSync(path.join(dir, 'result.json'), JSON.stringify(result));
    return body(dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}
const authorResult = (fields = {}) => {
  const { reuse, refused, ...rest } = fields;
  const decision = reuse ? 'reuse' : refused ? 'refuse' : 'author';
  return { decision, ...(decision === 'author' ? { outcome: 'authored' } : {}), folder: FOLDER, summary: 'Lengthens the session lifetime of the expiry test.', ...(reuse ? { reuse } : {}), ...(refused ? { refused } : {}), ...rest };
};
const twinBody = (folder) => renderSpecLine({ serverUrl: 'https://github.com', repository: 'octo/repo', branch: 'main' }, folder);

// The implementation pull request #9 of twin #5 (`specs/f`), stopped and diagnosed, and the prerequisite spec pull
// request #12 an authoring run created (`branch` speckit-fix/<folder> for one opened by earlier tooling).
function fixRepo({ files = null, spec = SPEC, branch = BRANCH, title = 'Spec: Upload session expiry' } = {}) {
  const github = diagnosisRepo({ amendment: false });
  github.issues[0].labels.push({ name: 'speckit:spec' });
  github.issues[0].body = twinBody('f');
  github.repo.branches[branch] = 'sha-fix';
  github.repo.commits['sha-fix'] = { tree: 't3', parents: ['sha-main'] };
  github.setFile('sha-fix', `${PREFIX}/spec.md`, spec);
  github.setFile('sha-fix', `${PREFIX}/plan.md`, PLAN);
  github.setFile('sha-fix', `${PREFIX}/tasks.md`, TASKS);
  github.setFile('sha-fix', `${PREFIX}/checklists/requirements.md`, '- [x] Requirements are testable\n');
  github.repo.pulls.push({ number: 12, node_id: 'PR_12', title, html_url: 'https://github.com/octo/repo/pull/12', body: 'Agent body <!-- speckit-fix:for {"pull":99} -->\n\n> Generated by [Spec Kit fix](https://github.com/octo/repo/actions/runs/1)\n\n<!-- gh-aw-agentic-workflow: Spec Kit fix, engine: copilot, id: 1 -->\n\n<!-- gh-aw-workflow-id: speckit-fix -->\n<!-- unterminated', draft: true, state: 'open', assignees: [], base: { ref: 'main', sha: 'sha-main' }, head: { ref: branch, sha: 'sha-fix', repo: { full_name: 'octo/repo' } }, created_at: github.tick() });
  github.repo.pullFiles[12] = files ?? [`${PREFIX}/spec.md`, `${PREFIX}/plan.md`, `${PREFIX}/tasks.md`, `${PREFIX}/checklists/requirements.md`];
  return github;
}

async function authored(github, extra = {}, actor = 'dev', fields = {}) {
  await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation: await github.getPullRequest(9), guidance: 'Make the test robust', actor, now: github.clock });
  const check = github.repo.checkRuns.at(-1);
  return withResult(authorResult(fields), (dir) => runRecord({ client: github, env: env({ SPECKIT_RESULT_DIR: dir, SPECKIT_CHECK_RUN: String(check.id), SPECKIT_CREATED_PULL: '12', ...extra }), log: silent }));
}

const addTwin = (github, number, folder, labels = []) => github.issues.push({ number, id: number * 1000, node_id: `I_${number}`, state: 'open', state_reason: null, title: `Twin ${number}`, body: twinBody(folder), labels: [{ name: 'speckit:spec' }, ...labels.map((name) => ({ name }))] });

test('records an authored spec: reports it, blocks the implementation, and starts its consistency check', async () => {
  const github = fixRepo();
  const result = await authored(github);
  assert.equal(result.outcome, 'created');
  assert.ok((await github.getPullRequest(9)).labels.some((label) => label.name === BLOCKED_LABEL));
  assert.ok(!(await github.getPullRequest(9)).labels.some((label) => label.name === ATTENTION_LABEL), 'a blocked implementation needs no command decision');
  const pull = github.repo.pulls.find((item) => item.number === 12);
  assert.match(pull.body, /^<!-- speckit-amend:status -->\n⏳ \*\*Being checked for consistency\.\*\*[\s\S]*\*\*Recommended next step\*\*: Wait for the consistency check[\s\S]*<!-- \/speckit-amend:status -->\n\nAgent body\n\n> Generated by \[Spec Kit fix\]\(https:\/\/github\.com\/octo\/repo\/actions\/runs\/1\)\n\n&lt;!-- unterminated$/);
  assert.doesNotMatch(pull.body, /speckit-fix:for/, 'no marker links it, and the forged one is removed');
  assert.doesNotMatch(pull.body, /gh-aw-/, 'no gh-aw footer markers show up as text');
  const created = github.comments.filter((item) => item.number === 9).at(-1);
  assert.match(created.body, /^<!-- speckit-fix:created \{"pull":12,"folder":"20261014-100000-upload-expiry"\} -->\n<!-- speckit-implement:blocked \{"pull":12,"stage":"review"\} -->\n\*\*Spec \[Spec: Upload session expiry \(#12\)\]\(https:\/\/github\.com\/octo\/repo\/pull\/12\) was authored\*\*[\s\S]*merged automatically[\s\S]*Lengthens the session lifetime[\s\S]*\*\*Blocked\*\* by spec #12: [\s\S]*- \*\*Next\*\*: #12 is checked for consistency and merged into `main` automatically[\s\S]*- \*\*To drop the spec\*\*: close #12 without merging/);
  assert.equal(github.comments.filter((item) => item.number === 9 && item.body.includes('speckit-implement:blocked')).length, 1, 'the label comes with exactly one explanation');
  const authoring = github.repo.checkRuns.find((check) => check.name === 'Spec Kit author');
  assert.deepEqual([authoring.status, authoring.conclusion, authoring.external_id], ['completed', 'success', 'speckit:fix-authored']);
  assert.match(github.comments.find((item) => item.number === 12).body, /This spec was requested with `\/speckit author` on #9[\s\S]*then it is merged automatically/);
  const analysis = github.repo.runs.at(-1);
  assert.deepEqual([analysis.workflow, analysis.inputs.kind, analysis.inputs.folder, analysis.inputs.amendment, analysis.inputs.pull], ['speckit-analyze.lock.yml', 'spec', FOLDER, '12', '9']);
  const context = await resolveAmendment(github, env(), 12);
  assert.deepEqual([context.kind, context.folder, context.implementation.number, context.twin], ['fix', FOLDER, 9, 5], 'found through the created event, without a marker');
});

test('a spec pull request on the earlier speckit-fix/ branch and with the earlier title is still recognized', async () => {
  const github = fixRepo({ branch: `speckit-fix/${FOLDER}`, title: 'Fix spec: Upload session expiry' });
  github.repo.pulls.find((item) => item.number === 12).body = 'Body <!-- speckit-fix:for {"pull":9,"twin":5,"folder":"f"} -->';
  assert.equal(await authoredFor(github, await github.getPullRequest(12)), 9, 'the legacy marker of its description');
  const context = await resolveAmendment(github, env(), 12);
  assert.deepEqual([context.kind, context.folder, context.implementation.number, context.twin], ['fix', FOLDER, 9, 5]);
  await startRework(github, env(), context, { mode: 'revise', feedback: { items: [] } });
  const rework = github.repo.runs.at(-1);
  assert.deepEqual([rework.workflow, rework.inputs.mode, rework.inputs.branch], ['speckit-author.yml', 'revise', undefined], 'the workflow finds the legacy branch by its folder');
  assert.equal(github.repo.pulls.find((item) => item.number === 12).title, 'Spec: Upload session expiry', 'renamed to the title prefix the rework\'s push requires');
  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-legacy-'));
  try {
    const { context: revise } = await runEvidence({ client: github, env: env({ SPECKIT_EVIDENCE_DIR: dir, SPECKIT_MODE: 'revise', SPECKIT_AMENDMENT: '12', SPECKIT_FOLDER: FOLDER }), log: silent });
    assert.equal(revise.branch, `speckit-fix/${FOLDER}`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
  github.closePull(12);
  assert.equal((await settleClosedFix(github, env(), { amendment: await github.getPullRequest(12), folder: FOLDER, implementation: await github.getPullRequest(9) })).outcome, 'discarded');
  assert.equal(github.repo.branches[`speckit-fix/${FOLDER}`], undefined, 'its own branch is deleted');
});

test('a spec is owned by the person who asked for it with /speckit author, from its creation to its review', async () => {
  const github = fixRepo();
  await authored(github, {}, 'fixer');
  const pull = github.repo.pulls.find((item) => item.number === 12);
  assert.deepEqual(pull.assignees, ['fixer'], 'assigned when it is created, not the implementation requester');
  assert.match(github.comments.find((item) => item.number === 12).body, /then it is merged automatically, or handed to @fixer for review when it changes `docs\/architecture\/`/);
  await presentAmendment(github, env(), await resolveAmendment(github, env(), 12), { consistent: true });
  assert.deepEqual(pull.assignees, ['fixer'], 'not assigned twice');
  assert.deepEqual(github.repo.reviewRequests, [{ number: 12, reviewers: ['fixer'] }]);
  for (const body of [
    pull.body,
    github.comments.filter((item) => item.number === 12).at(-1).body,
    github.comments.filter((item) => item.number === 9).at(-1).body,
  ]) {
    assert.equal(body.match(/\*\*Recommended next step\*\*/g)?.length, 1);
    assert.match(body, /\*\*Recommended next step\*\*: Review and merge spec \[#12\]\(https:\/\/github\.com\/octo\/repo\/pull\/12\)\./);
    assert.match(body, /Adds the spec to `main` and makes this spec depend on it once its twin exists; it is implemented once someone signs it off with `\/speckit implement` on that twin/);
    assert.match(body, /#9 waits and retries by itself once it is implemented/);
  }
  await presentAmendment(github, env(), await resolveAmendment(github, env(), 12), { consistent: false, problem: 'correction round did not finish' });
  for (const body of [
    pull.body,
    github.comments.filter((item) => item.number === 12).at(-1).body,
    github.comments.filter((item) => item.number === 9).at(-1).body,
  ]) {
    assert.equal(body.match(/\*\*Recommended next step\*\*/g)?.length, 1);
    assert.match(body, /\*\*Recommended next step\*\*: Post the following comment on spec \[#12\]/);
    assert.match(body, /```text\nPlease rework this spec [^\n]+\n```/);
    assert.doesNotMatch(body, /\*\*Recommended next step\*\*: Review and merge/);
  }
});

test('a missing, refused, or broken spec goes back to the implementation with the next steps', async () => {
  const none = fixRepo();
  const result = await authored(none, { SPECKIT_CREATED_PULL: '' });
  assert.equal(result.outcome, 'none');
  assert.match(none.comments.at(-1).body, /^\*\*No spec was created\*\*: Lengthens the session lifetime[\s\S]*\*\*Recommended next step\*\*: Retry what stopped[\s\S]*```text\n\/speckit retry\n```/);

  const broken = fixRepo({ files: [`${PREFIX}/spec.md`, 'src/platform/Tests/UploadSessionExpiryTests.cs'] });
  assert.equal((await authored(broken)).outcome, 'rejected');
  assert.equal(broken.repo.pulls.find((item) => item.number === 12).state, 'closed');
  assert.equal(broken.repo.branches[BRANCH], undefined);
  assert.match(broken.comments.at(-1).body, /^\*\*The authored spec #12 was rejected and closed\*\*: it changes files outside `specs\/20261014-100000-upload-expiry\/` and `docs\/architecture\/`: `src\/platform\/Tests\/UploadSessionExpiryTests\.cs`/);
  assert.equal(broken.repo.checkRuns.find((check) => check.name === 'Spec Kit author').conclusion, 'failure');

  const elsewhere = fixRepo({ branch: `feature/${FOLDER}` });
  assert.equal((await authored(elsewhere)).outcome, 'rejected');
  assert.match(elsewhere.comments.at(-1).body, /its branch `feature\/20261014-100000-upload-expiry` is not `speckit-spec\/<folder>`/);
});

test('checks a prerequisite spec: a new, publishable spec folder, without a Fix for line', async () => {
  const github = fixRepo();
  assert.doesNotMatch(SPEC, /Fix for/);
  assert.deepEqual((await checkFixSpec(github, { folder: FOLDER, pull: await github.getPullRequest(12) })).reasons, []);

  const listed = fixRepo({ files: [`${PREFIX}/spec.md`, `${PREFIX}/plan.md`, `${PREFIX}/tasks.md`, 'specs/README.md'] });
  const reasons = (await checkFixSpec(listed, { folder: FOLDER, pull: await listed.getPullRequest(12) })).reasons.join('\n');
  assert.match(reasons, /may only add `specs\/20261014-100000-upload-expiry\/` and change `docs\/architecture\/` \(specs\/README\.md lists no specs\), but it changes `specs\/README\.md`/);
  assert.doesNotMatch(reasons, /Fix for/);

  const existing = fixRepo({ files: [`${PREFIX}/spec.md`, 'docs/architecture/overview.md'] });
  existing.setFile('main', `${PREFIX}/spec.md`, SPEC);
  const more = (await checkFixSpec(existing, { folder: FOLDER, pull: await existing.getPullRequest(12) })).reasons.join('\n');
  assert.doesNotMatch(more, /may only add/, 'docs/architecture/ may change');
  assert.match(more, /it changes `docs\/architecture\/overview\.md`, but its plan lists no design decisions for it: name each decision behind these changes in the `## Architecture Updates` section/);
  assert.match(more, /already exists on `main`/);

  // The Design decisions comment satisfies the rule.
  const decided = fixRepo({ files: [...[`${PREFIX}/spec.md`, `${PREFIX}/plan.md`, `${PREFIX}/tasks.md`, `${PREFIX}/checklists/requirements.md`], 'docs/architecture/overview.md'] });
  await syncDesignDecisions(decided, 12, parseDesignDecisions([{ decision: 'Uploads expire after 10 minutes', why: 'Runner load delays the first part.', files: ['docs/architecture/overview.md'] }]));
  assert.deepEqual((await checkFixSpec(decided, { folder: FOLDER, pull: await decided.getPullRequest(12) })).reasons, []);
  await syncDesignDecisions(decided, 12, []);
  assert.match((await checkFixSpec(decided, { folder: FOLDER, pull: await decided.getPullRequest(12) })).reasons.join('\n'), /lists no design decisions/, 'a report without decisions empties the comment');
  assert.equal(decided.comments.filter((item) => item.number === 12).length, 1, 'one comment, updated in place');
});

test('a spec is reworked by Spec Kit author, and its evidence names the branch prefix and the spec that depends on it', async () => {
  const github = fixRepo();
  await authored(github);
  const context = await resolveAmendment(github, env(), 12);
  await startRework(github, env(), context, { mode: 'revise', feedback: { items: [{ kind: 'comment', author: 'dev', body: 'Keep the 2 s sweep check.', at: github.tick() }] } });
  const rework = github.repo.runs.at(-1);
  assert.deepEqual([rework.workflow, rework.inputs.mode, rework.inputs.amendment, rework.inputs.folder, rework.inputs.branch], ['speckit-author.yml', 'revise', '12', FOLDER, BRANCH]);
  // GitHub rejects a dispatch with an input the workflow does not declare.
  for (const run of github.repo.runs.filter((item) => item.workflow.endsWith('.lock.yml') || item.workflow === 'speckit-author.yml')) {
    const declared = declaredInputs(run.workflow.replace('.lock.yml', '.md'));
    assert.deepEqual(Object.keys(run.inputs).filter((name) => !declared.includes(name)), [], `${run.workflow} declares every input it is dispatched with`);
  }
  assert.match(github.comments.filter((item) => item.number === 12).at(-1).body, /\*\*Reworking this spec\*\* with the feedback from @dev/);

  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-evidence-'));
  try {
    await github.createComment(9, `${DIAGNOSIS_COMMENT_MARKER}\n**Diagnosis**: a flaky test from another feature.`);
    const { context: author } = await runEvidence({ client: github, env: env({ SPECKIT_EVIDENCE_DIR: dir, SPECKIT_STAMP: '20261014-100000' }), log: silent, now: () => github.clock });
    assert.deepEqual([author.folderPrefix, author.branchPrefix, author.titlePrefix, author.prerequisiteOf], ['20261014-100000-', 'speckit-spec/', 'Spec: ', 'specs/f']);
    assert.equal('fixForLine' in author, false, 'new specs carry no Fix for line');
    const evidence = readFileSync(path.join(dir, 'evidence.md'), 'utf8');
    assert.match(evidence, /## Guidance from the person who asked for the new spec\n\nMake the test robust/);
    assert.match(evidence, /## Latest diagnosis\n\n<!-- speckit-implement:diagnosis -->\n\*\*Diagnosis\*\*: a flaky test/);
    const { context: revise } = await runEvidence({ client: github, env: env({ SPECKIT_EVIDENCE_DIR: dir, SPECKIT_MODE: 'revise', SPECKIT_AMENDMENT: '12', SPECKIT_FOLDER: FOLDER, SPECKIT_GUIDANCE: 'Keep the sweep check.' }), log: silent });
    assert.deepEqual([revise.specDir, revise.branch, revise.fixPull, revise.baseBranch, revise.prerequisiteOf], [PREFIX, BRANCH, 12, 'main', 'specs/f']);
    assert.equal('fixForLine' in revise, false);
    assert.match(readFileSync(path.join(dir, 'evidence.md'), 'utf8'), /## Feedback on the spec to address\n\nKeep the sweep check\./);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('after the merge, the stopped spec depends on the new twin, which waits for /speckit implement; the implementation retries once it is implemented', async () => {
  const github = fixRepo();
  github.permissions.dev = 'write';
  await authored(github);
  github.closePull(12, { merged: true });
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  const maintain = () => maintainFixSpec(github, env(), { folder: 'f', implementation, twin: 5 }, { now: github.clock, report: silent });
  const dependency = () => maintainDependencyBlock(github, env(), { implementation, twin: 5 }, { report: silent });
  const blocked = () => (implementation.labels ?? []).some((label) => label.name === BLOCKED_LABEL);

  assert.deepEqual(await maintain(), { outcome: 'waiting', blocked: true }, 'the twin does not exist before Spec Kit prepare ran');
  assert.equal(blocked(), true);
  assert.equal((implementation.labels ?? []).some((label) => label.name === ATTENTION_LABEL), false, 'waiting for a prerequisite needs no command decision');
  assert.match(github.comments.filter((item) => item.number === 9).at(-1).body, /^<!-- speckit-fix:merged \{"pull":12,[\s\S]*<!-- speckit-implement:blocked \{"pull":12,"stage":"implement"\} -->\n\*\*Spec #12 was merged\*\* into `main` by a person[\s\S]*waits for sign-off with `\/speckit implement` on its twin[\s\S]*\*\*Blocked\*\* by spec #12[\s\S]*- \*\*Unblocks by itself\*\* once its spec twin is implemented/);
  assert.equal(github.repo.branches[BRANCH], undefined);

  addTwin(github, 30, FOLDER, ['speckit:stage:tasked', 'speckit:deps-pending']);
  assert.deepEqual(await maintain(), { outcome: 'waiting', blocked: true }, 'its dependency inference runs first');
  assert.deepEqual(github.edges, []);
  github.find(30).labels = github.find(30).labels.filter((label) => label.name !== 'speckit:deps-pending');
  assert.deepEqual(await maintain(), { outcome: 'linked', blocked: false });
  assert.deepEqual(github.edges, [[5, 30]], 'the stopped spec depends on the new spec like on any spec');
  assert.deepEqual(github.find(30).labels.map((label) => label.name).sort(), ['speckit:spec', 'speckit:stage:tasked'], 'not requested automatically');
  assert.equal(github.comments.filter((item) => item.number === 30).length, 0, 'nothing is written on the new twin');
  const linked = github.comments.filter((item) => item.number === 9).at(-1).body;
  assert.match(linked, /^<!-- speckit-fix:linked \{"pull":12,"folder":"20261014-100000-upload-expiry","twin":30\} -->\n<!-- speckit-implement:blocked \{"blockers":\[30\],"unrequested":\[30\]\} -->\n\*\*Spec #12 is spec twin \[#30\]\([^)]*\)\*\*, and this spec now depends on it\. @dev, you asked for it with `\/speckit author`/);
  assert.match(linked, /\*\*Recommended next step\*\*: Comment the following on spec twin #30 to request its implementation\.\n\n```text\n\/speckit implement\n```[\s\S]*`\/speckit-implement <folder>` locally for its folder does the same/);
  assert.equal(linked.match(/\*\*Recommended next step\*\*/g).length, 1);
  assert.equal(github.repo.runs.at(-1).workflow, 'speckit-orchestrate.yml');

  const comments = github.comments.length;
  assert.equal((await dependency()).outcome, 'blocked');
  assert.equal(github.comments.length, comments, 'the linking comment already explains the block');
  assert.equal((await maintain()).outcome, 'linked', 'nothing happens while the new spec waits');
  // Signed off: the block is explained again, without a next step for this pull request.
  github.find(30).labels.push({ name: 'speckit:stage:implement' });
  assert.equal((await dependency()).outcome, 'blocked');
  assert.match(github.comments.filter((item) => item.number === 9).at(-1).body, /^<!-- speckit-implement:blocked \{"blockers":\[30\]\} -->\n\*\*Blocked\*\* by prerequisite #30[^\n]*Nothing is needed on this pull request\./);
  assert.doesNotMatch(github.comments.filter((item) => item.number === 9).at(-1).body, /Recommended next step/);
  assert.match((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation, actor: 'dev', now: github.clock })).reason, /spec #12 was merged and is not implemented yet/);

  Object.assign(github.find(30), { state: 'closed', state_reason: 'completed' });
  assert.equal((await dependency()).outcome, 'retried');
  assert.equal(blocked(), false, 'implementing the new spec removes the hold');
  const retried = github.comments.filter((item) => item.number === 9).at(-1);
  assert.ok(retried.body.startsWith(RETRY_COMMENT_MARKER), 'the retry preserves the current phase base');
  assert.match(retried.body, /<!-- speckit-implement:unblocked -->\n\*\*The block is lifted\*\*: prerequisite #30 is implemented/);
  assert.deepEqual([github.repo.runs.at(-1).workflow, github.repo.runs.at(-1).inputs], ['speckit-implement-group.yml', { issue: '5', pull: '9', title: 'F', subject: 'P · T002 Next' }]);
  assert.equal((await dependency()).outcome, 'none', 'retried once');
  assert.equal((await maintain()).outcome, 'linked');
  assert.deepEqual(parseFixEvents(github.comments.filter((item) => item.number === 9)).map((event) => event.event), ['requested', 'created', 'merged', 'linked']);
  assert.equal((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation, actor: 'dev', now: github.clock })).started, true, 'an implemented spec allows another');
});

// Records an analysis of spec pull request #12 as the custom safe-output job of Spec Kit analyze would.
async function recordSpecAnalysis(github, report = { summary: 'No issues.', findings: [] }) {
  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-spec-analysis-'));
  try {
    const check = await github.createCheckRun({ name: 'Spec Kit amendment', head_sha: 'sha-fix', status: 'in_progress', external_id: 'speckit:amend-checking' });
    const output = path.join(dir, 'agent_output.json');
    writeFileSync(output, JSON.stringify({ items: [{ type: 'speckit_analysis', report: JSON.stringify(report) }] }));
    return await runRecordAnalysis({ client: github, env: env({ GH_AW_AGENT_OUTPUT: output, SPECKIT_AMENDMENT: '12', SPECKIT_ROUND: '0', SPECKIT_STALLS: '0', SPECKIT_MODE: 'loop', SPECKIT_CHECK_RUN: String(check.id), SPECKIT_DETECTION: 'success' }), log: silent });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

