test('linking never creates a dependency cycle: a reverse dependency is reported instead', async () => {
  const github = fixRepo();
  await authored(github);
  github.closePull(12, { merged: true });
  addTwin(github, 30, FOLDER);
  github.edges.push([30, 5]);
  const notes = [];
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  assert.deepEqual(await maintainFixSpec(github, env(), { implementation, twin: 5 }, { now: github.clock, report: (line) => notes.push(line) }), { outcome: 'cycle', blocked: true });
  assert.deepEqual(github.edges, [[30, 5]], 'no cycle');
  assert.match(notes.join('\n'), /spec twin #30 already depends on #5, so #5 cannot depend on it without a dependency cycle/);
  assert.deepEqual(await linkPrerequisite(github, { twin: 5, prerequisite: github.find(30) }), { linked: false, outcome: 'cycle' });
  github.edges.length = 0;
  github.edges.push([5, 30]);
  assert.deepEqual(await linkPrerequisite(github, { twin: 5, prerequisite: github.find(30) }), { linked: true }, 'an existing dependency counts');
  assert.deepEqual(github.edges, [[5, 30]]);
});

test('one cause, one spec: /speckit author on another implementation joins the existing one', async () => {
  const github = fixRepo();
  github.permissions.dev = 'write';
  await authored(github);
  github.issues.push({ number: 6, id: 6000, node_id: 'I_6', state: 'open', title: 'G', body: twinBody('g'), labels: [{ name: 'speckit:spec' }] });
  github.repo.pulls.push({ number: 20, node_id: 'PR_20', title: 'Implement: G', body: 'Closes #6', draft: true, state: 'open', labels: [], base: { ref: 'main' }, head: { ref: 'speckit/g', sha: 'sha-impl-g', repo: { full_name: 'octo/repo' } }, created_at: github.tick() });
  const second = env({ SPECKIT_TWIN: '6', SPECKIT_PULL: '20', SPECKIT_FOLDER: 'g' });

  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-join-'));
  try {
    const { context } = await runEvidence({ client: github, env: { ...second, SPECKIT_EVIDENCE_DIR: dir, SPECKIT_STAMP: '20261014-110000' }, log: silent, now: () => github.clock });
    assert.deepEqual(context.existingFixes, [{ pull: 12, folder: FOLDER, state: 'open', title: 'Spec: Upload session expiry' }]);
    const evidence = readFileSync(path.join(dir, 'evidence.md'), 'utf8');
    assert.match(evidence, /## Existing specs authored for stopped implementations\n\nOne cause gets one spec\.[\s\S]*report its pull request number in `reuse`/);
    assert.match(evidence, /### #12 Spec: Upload session expiry \(`specs\/20261014-100000-upload-expiry`, open pull request, asked for by #9\)\n\n# Feature Specification: Upload session expiry test/);

    await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 6, implementation: await github.getPullRequest(20), actor: 'dev', now: github.clock });
    const runs = github.repo.runs.length;
    const joined = await withResult({ decision: 'reuse', reuse: 12, summary: 'The same flaky expiry test stops this implementation.' }, (resultDir) => runRecord({ client: github, env: { ...second, SPECKIT_RESULT_DIR: resultDir, SPECKIT_CHECK_RUN: String(github.repo.checkRuns.at(-1).id), SPECKIT_CREATED_PULL: '' }, log: silent }));
    assert.deepEqual([joined.outcome, joined.pull], ['joined', 12]);
    assert.equal(github.repo.runs.length, runs, 'no second consistency check');
    assert.equal(github.repo.pulls.filter((pull) => String(pull.head.ref).startsWith('speckit-spec/')).length, 1, 'no second spec');
    assert.match(github.comments.filter((item) => item.number === 20).at(-1).body, /^<!-- speckit-fix:created \{"pull":12,"folder":"20261014-100000-upload-expiry","joined":true\} -->\n<!-- speckit-implement:blocked \{"pull":12,"stage":"review"\} -->\n\*\*This stop has the same cause as spec \[#12\]\(https:\/\/github\.com\/octo\/repo\/pull\/12\)\*\*[\s\S]*The same flaky expiry test/);
    assert.match(github.comments.filter((item) => item.number === 12).at(-1).body, /^\*\*Also unblocks #20\*\* \(`specs\/g`\)/);
    const authoring = github.repo.checkRuns.at(-1);
    assert.deepEqual([authoring.conclusion, authoring.output.title], ['success', 'Joined spec #12']);
    const implementation = github.repo.pulls.find((pull) => pull.number === 20);
    assert.ok(implementation.labels.some((label) => label.name === BLOCKED_LABEL));
    assert.equal((await resolveAmendment(github, env(), 12)).implementation.number, 9, 'it belongs to the implementation it was authored for');

    const maintain = (number, twin) => maintainFixSpec(github, env(), { implementation: github.repo.pulls.find((pull) => pull.number === number), twin }, { now: github.clock, report: silent });
    const before = github.repo.runs.length;
    assert.equal((await maintain(20, 6)).outcome, 'joined', 'the prerequisite spec is maintained by the implementation it was authored for');
    assert.equal(github.repo.runs.length, before);
    assert.match((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 6, implementation, actor: 'dev', now: github.clock })).reason, /spec #12 is still open/);

    github.closePull(12, { merged: true });
    addTwin(github, 30, FOLDER);
    const { context: merged } = await runEvidence({ client: github, env: { ...second, SPECKIT_EVIDENCE_DIR: dir, SPECKIT_STAMP: '20261014-120000' }, log: silent, now: () => github.clock });
    assert.deepEqual(merged.existingFixes, [{ pull: 12, folder: FOLDER, state: 'merged', title: 'Spec: Upload session expiry' }], 'a merged prerequisite an implementation waits for, found without a Fix for line');
    assert.equal((await maintain(9, 5)).outcome, 'linked');
    assert.equal((await maintain(20, 6)).outcome, 'linked');
    assert.deepEqual(github.edges, [[5, 30], [6, 30]], 'both stopped specs depend on the one prerequisite');
    Object.assign(github.find(30), { state: 'closed', state_reason: 'completed' });
    for (const [number, twin] of [[20, 6], [9, 5]]) {
      const result = await maintainDependencyBlock(github, env(), { implementation: github.repo.pulls.find((pull) => pull.number === number), twin }, { report: silent });
      assert.equal(result.outcome, 'retried');
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

